import { useEffect, useMemo, useState } from "react";
import {
  FaTimes,
  FaUniversity,
  FaImage,
  FaSave,
  FaPen,
  FaPlus,
  FaTrash,
  FaEnvelope,
  FaGlobe,
  FaMapMarkerAlt,
  FaHashtag,
  FaCalendarAlt,
  FaUserGraduate,
  FaChartLine,
  FaLink,
  FaBuilding,
} from "react-icons/fa";

const defaultForm = {
  universityname: "",
  universityid: "",
  university_admission_email: "",
  university_website: "",
  university_city: "",
  universitycountry: "",
  university_address: "",
  about_university: "",
  founded_date: "",
  type: "",
  calendar: "",
  students_count: "",
  acceptance_rate: "",
  graduation_rate: "",
  employability: "",
  qs_ranking: "",
  theworldranking: "",
  universitylogo: "",
  uniprofileimage: "",
  facebooklink: "",
  university_instagram: "",
  university_linkedin: "",
  university_x: "",
  university_youtube: "",
  Programs: [],
  media: [],
};

export default function UniversityProfilePortal({
  openPortal,
  closeUniversityPortal,
  university={
    "university_name": "University of Oxford",
    "university_id": "GBOXF001",
    "university_city": "Oxford",
    "students_count": "28,000+",
    "acceptance_rate": "35%",
    "qs_ranking": "Top 250",
    "about_university": "A globally oriented research university offering a diverse range of undergraduate Programs across Computer Science, Engineering, Informatics, and Humanities. The university combines academic rigor with strong industry collaboration, providing students with hands-on learning through laboratories, real-world projects, and internships with leading global companies. With a strong emphasis on innovation, employability, and international exposure, graduates are well-prepared for careers in technology, research, education, and creative industries.",
    "founded_date": "1965",
    "type": "Public Research University",
    "calendar": "Fall / Spring",
    "graduation_rate": "88%",
    "employability": "High",
    "Programs": null,
    "Media": [
        {
            "media_id": 2,
            "media": "\\",
            "media_file_name": "black screen.avif",
            "media_type": "image/avif",
            "media_size": "",
            "media_tag": "university_logo"
        },
        {
            "media_id": 3,
            "media": "\\",
            "media_file_name": "black screen.avif",
            "media_type": "image/avif",
            "media_size": "",
            "media_tag": "university_banner_image"
        },
        {
            "media_id": 4,
            "media": "\\",
            "media_file_name": "black screen.avif",
            "media_type": "image/avif",
            "media_size": "",
            "media_tag": "uni_profile_image"
        },
        {
            "media_id": 5,
            "media": "\\",
            "media_file_name": "black screen.avif",
            "media_type": "image/avif",
            "media_size": "",
            "media_tag": "university_logo"
        },
        {
            "media_id": 6,
            "media": "\\",
            "media_file_name": "black screen.avif",
            "media_type": "image/avif",
            "media_size": "",
            "media_tag": "university_banner_image"
        },
        {
            "media_id": 7,
            "media": "\\",
            "media_file_name": "black screen.avif",
            "media_type": "image/avif",
            "media_size": "",
            "media_tag": "uni_profile_image"
        }
    ],
    "university_admission_email": "admissions@ox.ac.uk",
    "university_email": "info@ox.ac.uk",
    "university_address": "University of Oxford, Wellington Square, Oxford OX1 2JD, United Kingdom",
    "university_phone": "+44 1865 270000",
    "university_website": "https://www.ox.ac.uk",
    "university_instagram": "https://www.instagram.com/oxford_uni",
    "university_youtube": "https://www.youtube.com/@UniversityofOxford",
    "university_linkedin": "https://www.linkedin.com/school/university-of-oxford/",
    "university_x": "https://x.com/UniofOxford"
},
  onSave,
  saving = false,
}) {
  const [activeTab, setActiveTab] = useState("data");
  const [editMode, setEditMode] = useState(true);
  const [formData, setFormData] = useState(defaultForm);

  useEffect(() => {
    if (university) {
      setFormData({
        universityname:  university?.university_name || "",
        universityid:  university?.university_id || "",
        university_admission_email:  university?.university_email || "",
        university_website:university?.university_website || "",
        university_city: university?.university_city || "",
        universitycountry:  university?.university_country || "",
        university_address: university?.university_address || "",
        about_university: university?.about_university || "",
        founded_date: university?.founded_date || "",
        type: university?.type || "",
        calendar: university?.calendar || "",
        students_count: university?.students_count || "",
        acceptance_rate: university?.acceptance_rate || "",
        graduation_rate: university?.graduation_rate || "",
        employability: university?.employability || "",
        qs_ranking: university?.qs_ranking || university?.qs_ranking || "",
        theworldranking: university?.theworldranking || "",
        universitylogo: university?.universitylogo || university?.university_logo || "",
        uniprofileimage:
          university?.uniprofileimage || university?.university_image || "",
        facebooklink: university?.facebooklink || "",
        university_instagram: university?.university_instagram || "",
        university_linkedin: university?.university_linkedin || "",
        university_x: university?.university_x || "",
        university_youtube: university?.university_youtube || "",
        Programs: Array.isArray(university?.Programs) ? university.Programs : [],
        media: Array.isArray(university?.media)
          ? university.media
          : Array.isArray(university?.Media)
          ? university.Media
          : [],
      });
    //   setActiveTab("data");
    }
  }, [university]);

  const mediaItems = useMemo(() => {
    const extraMedia = Array.isArray(formData.media) ? formData.media : [];

    const baseMedia = [
      formData.universitylogo
        ? {
            id: "logo",
            type: "Logo",
            url: formData.universitylogo,
          }
        : null,
      formData.uniprofileimage
        ? {
            id: "profile",
            type: "Profile",
            url: formData.uniprofileimage,
          }
        : null,
    ].filter(Boolean);

    return [...baseMedia, ...extraMedia];
  }, [formData]);

  const handleChange = (field, value) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const handleProgramChange = (index, value) => {
    const updated = [...formData.Programs];
    updated[index] = value;
    setFormData((prev) => ({
      ...prev,
      Programs: updated,
    }));
  };

  const addProgram = () => {
    setFormData((prev) => ({
      ...prev,
      Programs: [...prev.Programs, ""],
    }));
  };

  const removeProgram = (index) => {
    setFormData((prev) => ({
      ...prev,
      Programs: prev.Programs.filter((_, i) => i !== index),
    }));
  };

  const handleSave = () => {
    if (onSave) onSave(formData);
  };

  return (
    <>
      {/* Backdrop */}
      <div
        onClick={closeUniversityPortal}
        className={`fixed inset-0 bg-slate-900/20 backdrop-blur-[1px] z-40 transition-all duration-300 ${
          openPortal ? "opacity-100 visible" : "opacity-0 invisible"
        }`}
      />

      {/* Drawer */}
      <div
        className={`fixed top-0 right-0 h-screen w-full sm:w-[440px] lg:w-[520px] bg-white border-r border-slate-200 shadow-2xl z-50 transform transition-transform duration-300 ease-in-out ${
          openPortal ? "translate-x-0" : "translate-x-full"
        }`}
      >
        <div className="h-full flex flex-col">
          {/* Header */}
          <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
            <div className="flex items-start justify-between gap-4">
              <div className="flex items-center gap-3 min-w-0">
                <div className="w-12 h-12 rounded-xl border border-slate-200 bg-white overflow-hidden flex items-center justify-center">
                  {formData.uniprofileimage ? (
                    <img
                      src={formData.uniprofileimage}
                      alt={formData.universityname}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <FaUniversity className="text-slate-400 text-lg" />
                  )}
                </div>

                <div className="min-w-0">
                  <h2 className="text-sm font-bold text-slate-900 truncate">
                    {formData.universityname || "University Profile"}
                  </h2>
                  <p className="text-[11px] text-slate-500 font-mono mt-1">
                    {formData.universityid || "N/A"}
                  </p>
                </div>
              </div>

              <button
                onClick={closeUniversityPortal}
                className="w-9 h-9 rounded-full bg-white border border-slate-200 flex items-center justify-center text-slate-500 hover:bg-slate-100 transition"
              >
                <FaTimes className="text-sm" />
              </button>
            </div>

            <div className="flex items-center gap-2 mt-4">
              <button
                onClick={() => setEditMode((prev) => !prev)}
                className={`inline-flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-bold border transition ${
                  editMode
                    ? "bg-indigo-50 text-indigo-700 border-indigo-200"
                    : "bg-white text-slate-600 border-slate-200 hover:bg-slate-100"
                }`}
              >
                <FaPen className="text-[11px]" />
                {editMode ? "Editing Enabled" : "Enable Editing"}
              </button>

              <button
                onClick={handleSave}
                disabled={saving}
                className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-indigo-600 text-white text-xs font-bold hover:bg-indigo-700 disabled:opacity-50 transition"
              >
                <FaSave className="text-[11px]" />
                {saving ? "Saving..." : "Save Changes"}
              </button>
            </div>

            {/* Tabs */}
            <div className="mt-4 flex items-center gap-2 border-b border-slate-200">
              <button
                onClick={() => setActiveTab("data")}
                className={`px-4 py-2 text-xs font-bold border-b-2 transition ${
                  activeTab === "data"
                    ? "border-indigo-600 text-indigo-600"
                    : "border-transparent text-slate-500 hover:text-slate-700"
                }`}
              >
                Data
              </button>

              <button
                onClick={() => setActiveTab("media")}
                className={`px-4 py-2 text-xs font-bold border-b-2 transition ${
                  activeTab === "media"
                    ? "border-indigo-600 text-indigo-600"
                    : "border-transparent text-slate-500 hover:text-slate-700"
                }`}
              >
                Media
              </button>
            </div>
          </div>

          {/* Body */}
          <div className="flex-1 overflow-y-auto px-5 py-5 space-y-6">
            {activeTab === "data" && (
              <>
                <Section title="Basic Information" icon={<FaBuilding />}>
                  <div className="grid grid-cols-1 gap-4">
                    <Field
                      label="University Name"
                      value={formData.universityname}
                      onChange={(e) =>
                        handleChange("universityname", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="University ID"
                      value={formData.universityid}
                      onChange={(e) =>
                        handleChange("universityid", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Type"
                      value={formData.type}
                      onChange={(e) => handleChange("type", e.target.value)}
                      disabled={!editMode}
                    />
                    <Field
                      label="Founded Date"
                      value={formData.founded_date}
                      onChange={(e) =>
                        handleChange("founded_date", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Academic Calendar"
                      value={formData.calendar}
                      onChange={(e) => handleChange("calendar", e.target.value)}
                      disabled={!editMode}
                    />
                  </div>
                </Section>

                <Section title="Contact Details" icon={<FaEnvelope />}>
                  <div className="grid grid-cols-1 gap-4">
                    <Field
                      label="Email"
                      value={formData.university_admission_email}
                      onChange={(e) =>
                        handleChange("university_admission_email", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Website"
                      value={formData.university_website}
                      onChange={(e) =>
                        handleChange("university_website", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="City"
                      value={formData.university_city}
                      onChange={(e) =>
                        handleChange("university_city", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Country"
                      value={formData.universitycountry}
                      onChange={(e) =>
                        handleChange("universitycountry", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Address"
                      value={formData.university_address}
                      onChange={(e) =>
                        handleChange("university_address", e.target.value)
                      }
                      disabled={!editMode}
                    />
                  </div>
                </Section>

                <Section title="About University" icon={<FaUniversity />}>
                  <TextAreaField
                    label="Description"
                    value={formData.about_university}
                    onChange={(e) =>
                      handleChange("about_university", e.target.value)
                    }
                    disabled={!editMode}
                    rows={6}
                  />
                </Section>

                <Section title="Statistics & Rankings" icon={<FaChartLine />}>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Field
                      label="Students Count"
                      value={formData.students_count}
                      onChange={(e) =>
                        handleChange("students_count", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Acceptance Rate"
                      value={formData.acceptance_rate}
                      onChange={(e) =>
                        handleChange("acceptance_rate", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Graduation Rate"
                      value={formData.graduation_rate}
                      onChange={(e) =>
                        handleChange("graduation_rate", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Employability"
                      value={formData.employability}
                      onChange={(e) =>
                        handleChange("employability", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="QS Ranking"
                      value={formData.qs_ranking}
                      onChange={(e) =>
                        handleChange("qs_ranking", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="World Ranking"
                      value={formData.theworldranking}
                      onChange={(e) =>
                        handleChange("theworldranking", e.target.value)
                      }
                      disabled={!editMode}
                    />
                  </div>
                </Section>

                <Section title="Social Links" icon={<FaLink />}>
                  <div className="grid grid-cols-1 gap-4">
                    <Field
                      label="Facebook"
                      value={formData.facebooklink}
                      onChange={(e) =>
                        handleChange("facebooklink", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Instagram"
                      value={formData.university_instagram}
                      onChange={(e) =>
                        handleChange("university_instagram", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="LinkedIn"
                      value={formData.university_linkedin}
                      onChange={(e) =>
                        handleChange("university_linkedin", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="Twitter / X"
                      value={formData.university_x}
                      onChange={(e) =>
                        handleChange("university_x", e.target.value)
                      }
                      disabled={!editMode}
                    />
                    <Field
                      label="YouTube Video"
                      value={formData.university_youtube}
                      onChange={(e) =>
                        handleChange("university_youtube", e.target.value)
                      }
                      disabled={!editMode}
                    />
                  </div>
                </Section>

                <Section title="Programs" icon={<FaUserGraduate />}>
                  <div className="space-y-3">
                    {formData.Programs?.length > 0 ? (
                      formData.Programs.map((program, index) => (
                        <div
                          key={index}
                          className="flex items-center gap-2"
                        >
                          <input
                            type="text"
                            value={program}
                            onChange={(e) =>
                              handleProgramChange(index, e.target.value)
                            }
                            disabled={!editMode}
                            placeholder={`Program ${index + 1}`}
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm outline-none focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100 disabled:bg-slate-100 disabled:text-slate-500"
                          />
                          {editMode && (
                            <button
                              type="button"
                              onClick={() => removeProgram(index)}
                              className="w-10 h-10 rounded-xl border border-red-200 bg-red-50 text-red-600 flex items-center justify-center hover:bg-red-100 transition"
                            >
                              <FaTrash className="text-xs" />
                            </button>
                          )}
                        </div>
                      ))
                    ) : (
                      <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 px-4 py-4 text-sm text-slate-400">
                        No Programs added yet
                      </div>
                    )}

                    {editMode && (
                      <button
                        type="button"
                        onClick={addProgram}
                        className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-slate-900 text-white text-xs font-bold hover:bg-slate-800 transition"
                      >
                        <FaPlus className="text-[10px]" />
                        Add Program
                      </button>
                    )}
                  </div>
                </Section>
              </>
            )}

            {activeTab === "media" && (
              <>
                <Section title="Primary Media" icon={<FaImage />}>
                  <div className="space-y-4">
                    <MediaInputCard
                      label="University Logo"
                      value={formData.universitylogo}
                      preview={formData.universitylogo}
                      onChange={(e) =>
                        handleChange("universitylogo", e.target.value)
                      }
                      disabled={!editMode}
                    />

                    <MediaInputCard
                      label="Profile Image"
                      value={formData.uniprofileimage}
                      preview={formData.uniprofileimage}
                      onChange={(e) =>
                        handleChange("uniprofileimage", e.target.value)
                      }
                      disabled={!editMode}
                    />
                  </div>
                </Section>

                <Section title="All Media" icon={<FaImage />}>
                  {mediaItems.length > 0 ? (
                    <div className="grid grid-cols-1 gap-4">
                      {mediaItems.map((item, index) => {
                        const mediaUrl =
                          item?.url ||
                          item?.media ||
                          item?.path ||
                          item?.image ||
                          item?.file ||
                          "";

                        return (
                          <div
                            key={item?.id || index}
                            className="rounded-2xl border border-slate-200 overflow-hidden bg-white"
                          >
                            <div className="h-44 bg-slate-100 flex items-center justify-center overflow-hidden">
                              {mediaUrl ? (
                                <img
                                //   src={mediaUrl}
                                  alt={item?.media_file_name}
                                  className="w-full h-full object-cover"
                                />
                              ) : (
                                <div className="text-slate-400 text-sm">
                                  No preview available
                                </div>
                              )}
                            </div>

                            
                          </div>
                        );
                      })}
                    </div>
                  ) : (
                    <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 px-4 py-6 text-sm text-slate-400">
                      No media found
                    </div>
                  )}
                </Section>
              </>
            )}
          </div>
        </div>
      </div>
    </>
  );
}

function Section({ title, icon, children }) {
  return (
    <section className="rounded-2xl border border-slate-200 bg-white shadow-sm overflow-hidden">
      <div className="px-4 py-3 border-b border-slate-100 bg-slate-50 flex items-center gap-2">
        <span className="text-slate-400 text-xs">{icon}</span>
        <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500">
          {title}
        </h3>
      </div>
      <div className="p-4">{children}</div>
    </section>
  );
}

function Field({ label, value, onChange, disabled = false }) {
  return (
    <div>
      <label className="block text-[11px] font-bold uppercase tracking-wider text-slate-400 mb-2">
        {label}
      </label>
      <input
        type="text"
        value={value || ""}
        onChange={onChange}
        disabled={disabled}
        className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-700 outline-none focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100 disabled:bg-slate-100 disabled:text-slate-500"
      />
    </div>
  );
}

function TextAreaField({
  label,
  value,
  onChange,
  disabled = false,
  rows = 5,
}) {
  return (
    <div>
      <label className="block text-[11px] font-bold uppercase tracking-wider text-slate-400 mb-2">
        {label}
      </label>
      <textarea
        rows={rows}
        value={value || ""}
        onChange={onChange}
        disabled={disabled}
        className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-sm text-slate-700 outline-none resize-none focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100 disabled:bg-slate-100 disabled:text-slate-500"
      />
    </div>
  );
}

function MediaInputCard({ label, value, preview, onChange, disabled }) {
  return (
    <div className="rounded-2xl border border-slate-200 overflow-hidden bg-white">
      <div className="h-44 bg-slate-100 overflow-hidden flex items-center justify-center">
        {preview ? (
          <img
            src={preview}
            alt={label}
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="text-slate-400 text-sm">No preview</div>
        )}
      </div>
      <div className="p-4">
        <label className="block text-[11px] font-bold uppercase tracking-wider text-slate-400 mb-2">
          {label}
        </label>
        <input
          type="text"
          value={value || ""}
          onChange={onChange}
          disabled={disabled}
          placeholder={`Paste ${label.toLowerCase()} URL`}
          className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-700 outline-none focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100 disabled:bg-slate-100 disabled:text-slate-500"
        />
      </div>
    </div>
  );
}